from functools import lru_cache

def factorial(n: int) -> int:
    """
    Compute n! (factorial of n) using recursion with memoization.

    Parameters
    ----------
    n : int
        A non-negative integer (0 ≤ n ≤ 100).

    Returns
    -------
    int
        The factorial of n.
    """

    if n < 0:
        raise ValueError("factorial() is only defined for non-negative integers.")

    @lru_cache(maxsize=None)
    def _fact(k: int) -> int:
        if k in (0, 1):
            return 1
        return k * _fact(k - 1)

    return _fact(n)

